-- Additive official enrollment evidence, never alters notes or academic results.
CREATE TABLE IF NOT EXISTS enrollment_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,filename TEXT NOT NULL,storage_name TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,size BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'uploaded',parser_version TEXT NOT NULL DEFAULT '',extracted_text TEXT NOT NULL DEFAULT '',created_by BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,created_at TEXT NOT NULL,analyzed_at TEXT,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS enrollment_rows(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL REFERENCES enrollment_documents(id) DEFERRABLE INITIALLY IMMEDIATE,line_number BIGINT NOT NULL,student_name TEXT NOT NULL,identifier TEXT NOT NULL DEFAULT '',card_number TEXT NOT NULL DEFAULT '',level TEXT NOT NULL DEFAULT '',track TEXT NOT NULL DEFAULT '',year_label TEXT NOT NULL DEFAULT '',match_user_id BIGINT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,score BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'review',reason TEXT NOT NULL DEFAULT '',validated_at TEXT,validated_by BIGINT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,UNIQUE(document_id,line_number));
CREATE INDEX IF NOT EXISTS idx_enrollment_rows_document ON enrollment_rows(document_id,status);
